/** Resume reconstruction: rebuild the controller's scheduler memory from the
 * durable transport record. Nothing here invents game facts — frozen actions,
 * dice, staged candidates and the working cursor are read from the record, and
 * only unconfirmed model text (results/updates/narration for the open group)
 * is regenerated by the ordinary scheduler. */
import { canonicalJson } from '../canonical';
import { clone } from '../state';
import { foldIdentity, PROGRAM_ROLL_RULE, type ControllerMemory, type PendingTarget, type PlannedPoint, type SourceAnalysis, type StagedUnit } from '../../schedule';
import type { ControlState, Id, PointWork, TimeAdvance, WorldContext } from '../../types';
import type { LocalGameSnapshot } from '../session';

type LocalRecord = LocalGameSnapshot['transport'];
type WorkRecord = NonNullable<LocalRecord['work']>;
type GroupRecord = NonNullable<WorkRecord['pendingGroup']>;

/** The only session memory that is not derivable from the record: which point
 * the model planned for the open round. It is a resume hint, validated against
 * the record before use (never a second game fact). */
export interface LocalSchedulerCheckpoint {
  roundId: Id;
  plan: PlannedPoint[];
  planIndex: number;
}

export interface ResumeServedState {
  world: WorldContext;
  control: ControlState;
  work: PointWork | null;
  activeInput: { advanceId: Id; inputId: Id; text: string } | null;
}

export interface ResumeRebuildInput {
  record: LocalRecord;
  context: ResumeServedState;
  memory: ControllerMemory;
  checkpoint?: LocalSchedulerCheckpoint | null;
}

export interface ResumeRebuildResult {
  memory: ControllerMemory;
  /** What happened, for logs and tests. */
  notes: string[];
  /** Group identity slots that still need program allocation before the next
   * actor can act. */
  groupSlots: { slotKey: Id; kind: 'group' }[];
  resumeAllocationKey: Id | null;
}

function committedPoints(record: LocalRecord) {
  return Object.values(record.points).sort((a, b) => a.sequence - b.sequence);
}

function roundPoints(record: LocalRecord, roundId: Id) {
  return committedPoints(record).filter((point) => point.roundId === roundId);
}

function sameTime(a: PlannedPoint, work: { timeAdvance: TimeAdvance }): boolean {
  return canonicalJson(a.timeAdvance) === canonicalJson(work.timeAdvance);
}

/** A saved plan is usable only when every committed point of the open round
 * matches its prefix and the in-progress work matches the next entry. */
function planUsable(record: LocalRecord, checkpoint: LocalSchedulerCheckpoint): boolean {
  if (!Array.isArray(checkpoint.plan) || checkpoint.plan.length === 0) return false;
  if (!Number.isInteger(checkpoint.planIndex) || checkpoint.planIndex < 0 || checkpoint.planIndex > checkpoint.plan.length) return false;
  const committed = roundPoints(record, checkpoint.roundId);
  if (committed.length !== checkpoint.planIndex) return false;
  for (let index = 0; index < committed.length; index++) {
    if (checkpoint.plan[index]?.pointId !== committed[index].id) return false;
  }
  const work = record.work;
  if (work) {
    const planned = checkpoint.plan[checkpoint.planIndex];
    if (!planned || planned.pointId !== work.pointId || planned.kind !== work.kind || !sameTime(planned, work)) return false;
  }
  return true;
}

/** The DFS ancestry of the open group's current source: each admitted member
 * was admitted by exactly one roll, so walking those rolls back to the
 * initiator reconstructs the stack without inventing order. */
function ancestry(record: LocalRecord, groupId: Id, pending: GroupRecord): Id[] {
  const group = pending;
  const chain: Id[] = [group.sourceId];
  const seen = new Set<Id>(chain);
  let current = group.sourceId;
  for (;;) {
    const parent = Object.values(record.rolls).find((roll) => roll.groupId === groupId && roll.admitted && roll.targetId === current);
    if (!parent || !group.memberIds.includes(parent.sourceId) || seen.has(parent.sourceId)) break;
    seen.add(parent.sourceId);
    chain.push(parent.sourceId);
    current = parent.sourceId;
  }
  return chain;
}

function compareTargets(a: { targetId: Id; triggerKey: Id }, b: { targetId: Id; triggerKey: Id }): number {
  if (a.targetId !== b.targetId) return a.targetId < b.targetId ? -1 : 1;
  if (a.triggerKey === b.triggerKey) return 0;
  return a.triggerKey < b.triggerKey ? -1 : 1;
}

function frameFor(record: LocalRecord, pending: GroupRecord, sourceId: Id): SourceAnalysis {
  const group = pending;
  const specs = group.targetSpecsBySource[sourceId] ?? null;
  const pendingTargets: PendingTarget[] = [];
  const rolled: SourceAnalysis['rolled'] = [];
  for (const spec of [...(specs ?? [])].sort(compareTargets)) {
    const roll = record.rolls[`${sourceId}|${spec.targetId}|${spec.triggerKey}`];
    if (!roll) {
      pendingTargets.push({ targetId: spec.targetId, triggerKey: spec.triggerKey, rule: PROGRAM_ROLL_RULE });
      continue;
    }
    rolled.push({
      targetId: spec.targetId, triggerKey: spec.triggerKey,
      rule: { ruleVersion: roll.ruleVersion, target: roll.target },
      rollId: roll.rollId, admitted: roll.admitted,
      // A threat is reacted once its target was admitted into the group (the
      // only way a target becomes a member).
      reacted: group.memberIds.includes(spec.targetId),
    });
  }
  return { sourceId, actionText: group.actionTexts[sourceId] ?? '', targetsExtended: specs != null, pendingTargets, rolled };
}

function frameComplete(frame: SourceAnalysis): boolean {
  return frame.targetsExtended && frame.pendingTargets.length === 0
    && frame.rolled.every((roll) => roll.reacted || roll.admitted !== true);
}

function groupActionsOf(record: LocalRecord, pending: GroupRecord): ControllerMemory['groupActions'] {
  const group = pending;
  return [...group.memberIds].reverse().filter((member) => group.actionTexts[member] != null).map((member) => ({
    memberId: member,
    actionText: group.actionTexts[member] as string,
    rolls: Object.values(record.rolls)
      .filter((roll) => roll.groupId === group.groupId && roll.sourceId === member)
      .map((roll) => ({ targetId: roll.targetId, rollId: roll.rollId, result: roll.result, eligible: roll.eligible, admitted: roll.admitted })),
  }));
}

export function rebuildSessionMemory(input: ResumeRebuildInput): ResumeRebuildResult {
  const { record, memory } = input;
  const notes: string[] = [];
  memory.leaseToken = record.lease?.leaseToken ?? null;
  memory.playerAdvance = record.advance
    ? { advanceId: record.advance.advanceId, inputId: record.advance.inputId, text: record.advance.inputText }
    : null;
  // A pause saved by the dead tab is external to this new session: it must be
  // reported as a server/record pause, and this session's budget is fresh.
  memory.localPause = false;

  const round = record.round;
  const work = record.work;
  const points = round ? roundPoints(record, round.roundId) : [];
  memory.roundChanges = round && points.length
    ? { roundId: round.roundId, points: points.map((point) => ({ pointId: point.id, timeAdvance: clone(point.timeAdvance), entityDeltas: clone(point.entityDeltas) })) }
    : null;

  let plan: PlannedPoint[] | null = null;
  let planIndex = 0;
  if (round) {
    const checkpoint = input.checkpoint ?? null;
    if (checkpoint && checkpoint.roundId === round.roundId && planUsable(record, checkpoint)) {
      plan = clone(checkpoint.plan);
      planIndex = checkpoint.planIndex;
      notes.push('plan_restored');
    } else if (work) {
      // The open point is already frozen in the record; the local planner's
      // contract is one point per round covering the frozen order.
      plan = [{ pointId: work.pointId, kind: work.kind, timeAdvance: clone(work.timeAdvance), actorIds: [...round.order] }];
      planIndex = 0;
      notes.push('plan_synthesized_from_work');
    } else if (points.length > 0) {
      const acted = new Set<Id>([...round.visitedIds, ...round.actedIds]);
      const remaining = round.order.filter((actor) => !acted.has(actor));
      plan = [{ pointId: `point_${round.roundId}_${points.length + 1}`, kind: 'normal',
        timeAdvance: { boundary: 'elapsed', duration: { amount: 1, unit: 'minute' } },
        actorIds: remaining.length ? remaining : [...round.order] }];
      planIndex = 0;
      notes.push('plan_synthesized_after_commit');
    } else {
      notes.push('plan_pending_model');
    }
  }
  memory.plan = plan;
  memory.planIndex = planIndex;

  const groupActors = new Set<Id>([...(round?.visitedIds ?? []), ...(round?.actedIds ?? [])]);
  const staged: StagedUnit[] = [];
  if (work) {
    for (const actor of work.working.visitedIds) groupActors.add(actor);
    for (const actor of work.working.actedIds) groupActors.add(actor);
    for (const unit of work.units) {
      staged.push({ groupId: unit.groupId, actorIds: [...unit.memberIds], candidates: clone(unit.candidates), results: clone(unit.results) });
    }
    memory.staged = staged;
    memory.stagedTimeScan = work.timeScan ? clone(work.timeScan) : null;
    const pending = work.pendingGroup;
    if (pending) {
      for (const member of pending.memberIds) groupActors.add(member);
      const frames = ancestry(record, pending.groupId, pending).map((sourceId) => frameFor(record, pending, sourceId));
      let start = 0;
      while (start < frames.length && frameComplete(frames[start])) start += 1;
      memory.sources = start < frames.length ? frames.slice(start) : [];
      memory.groupActions = groupActionsOf(record, pending);
      if (start > 0) notes.push(`sources_retired:${start}`);
    } else {
      memory.sources = [];
      memory.groupActions = [];
    }
    memory.workingState = null;
    memory.commitPayload = null;
    memory.lastResults = null;
    memory.restoredUnit = null;
    memory.lastModel = null;
    memory.lastTargets = null;
    memory.updatesCalls = [];
    memory.updatesApplied = 0;
    memory.updatesPendingRefs = [];
    memory.updatesPreviewSkipped = 0;
    memory.continuation = null;
    memory.successorTime = null;
    memory.narration = null;
    if (work.sealed) notes.push('work_sealed');
    if (work.pendingGroup?.closed) notes.push('group_closed');
  } else {
    memory.staged = [];
    memory.stagedTimeScan = null;
    memory.sources = [];
    memory.groupActions = [];
    memory.narration = null;
    // No open point: the committed head state IS the current state, so the
    // continuation assessment (and any between-point decision) can read it
    // without another preview. It is never a synthesized state.
    memory.workingState = round ? { key: `committed:${record.headPointId}`, state: clone(record.state) } : null;
    memory.commitPayload = null;
  }
  memory.groupActors = [...groupActors].sort();

  const active = !!round && record.advance != null && record.control.phase !== 'complete' && record.control.phase !== 'assess_continuation';
  const remaining = active ? round!.order.filter((actor) => !memory.groupActors.includes(actor)) : [];
  const groupSlots = remaining.map((actor) => ({ slotKey: `group:${actor}` as Id, kind: 'group' as const }));
  const resumeAllocationKey = groupSlots.length
    ? `resume_${foldIdentity(record.worldId, round!.roundId, work?.pointId ?? `slot_${planIndex}`)}`
    : null;
  return { memory, notes, groupSlots, resumeAllocationKey };
}
